export function createPresentationScope(){const cancelled=()=>Object.assign(new Error('PRESENTATION_DISPOSED'),{code:'PRESENTATION_DISPOSED'}),controller=new AbortController(),waiting=new Set();let disposed=false;const wrap=fn=>{if(typeof fn!=='function')throw Error('PRESENTATION_FUNCTION_REQUIRED');return(...args)=>{if(disposed)return Promise.reject(cancelled());return new Promise((resolve,reject)=>{let settled=false;const finish=(ok,value)=>{if(settled)return;settled=true;waiting.delete(cancel);ok?resolve(value):reject(value)},cancel=()=>finish(false,cancelled());waiting.add(cancel);Promise.resolve().then(()=>disposed?undefined:fn(...args,controller.signal)).then(v=>finish(true,v),e=>finish(false,e))})}};return Object.freeze({signal:controller.signal,wrap,dispose(){if(disposed)return;disposed=true;for(const cancel of [...waiting])cancel();controller.abort()},get pending(){return waiting.size}})}
